export interface Event {
  userId: string
  type: string
  timestamp: number
  value: number
}

// Complexity: before O(n^2) (nested loop scanning all events for each event) -> after O(n) (single filter pass)
export function getEventsForUser(events: Event[], userId: string): Event[] {
  return events.filter(event => event.userId === userId)
}

// Complexity: before O(n * t) where t = number of distinct types (one full filter pass per type) -> after O(n) (single pass accumulating counts and totals)
export function getSummaryByType(events: Event[]): Record<string, { count: number; total: number; avg: number }> {
  const summary: Record<string, { count: number; total: number; avg: number }> = {}
  for (const event of events) {
    const entry = summary[event.type] ?? (summary[event.type] = { count: 0, total: 0, avg: 0 })
    entry.count++
    entry.total += event.value
  }
  for (const type of Object.keys(summary)) {
    summary[type].avg = summary[type].total / summary[type].count
  }
  return summary
}
